import json,sys
d=json.load(sys.stdin)
items=d['items'] if isinstance(d,dict) else d
LIVE={'pic-a','pic-b','pic-c','pic-d','pic-e','pic-f','pic-g','pic-h'}
byid={i['id']:i for i in items}
kids={}
for i in items: kids.setdefault(i.get('parent') or '',[]).append(i['id'])
def desc(x):
    o=[]
    for c in kids.get(x,[]): o.append(c); o+=desc(c)
    return o
print('--- OWNER CENSUS (all statuses) ---')
from collections import Counter
print(Counter(i.get('owner','') or '(none)' for i in items))
print()
print('--- DEAD-LANE OWNERS ---')
for i in items:
    o=i.get('owner','')
    if o and o not in LIVE: print('  ',i['id'],'owner=',o,'status=',i['status'])
print()
print('--- ACTIVE ROWS: does subtree contain an ACTIVE row owned by a live lane? ---')
for i in items:
    if i['status']!='active': continue
    ds=desc(i['id'])
    liveact=[x for x in ds if byid[x]['status']=='active' and byid[x].get('owner','') in LIVE and byid[x].get('owner','')]
    kind='LEAF' if not kids.get(i['id']) else 'CONE(%d)'%len(kids[i['id']])
    print('%-70s %-9s owner=%-7s liveActiveDesc=%s' % (i['id'], kind, i.get('owner','') or '-', liveact if liveact else 'NONE'))
